		t.Fatal(err)
	}
	gauntletEvidenceFile(t, harness, "run-fail.json")
	if err := os.WriteFile(filepath.Join(harness, "issues", "ISS-1.md"), []byte("# issue\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	runner := &smokeRecordingRunner{
		discovery: gauntletDiscovery(sp),
		run: smokeRunResponse{SchemaVersion: 1, ProtocolVersion: "1.0", HarnessID: "fake", RunID: "run-fail", ScopeKind: "suite", Scope: []string{"suite-a", "suite-b"},
			Counts: SmokeCountsWire{Total: 2, Passed: 1, Failed: 1}, DurationMs: 5,
			Tests:   []SmokeTestResult{{ID: "live-a", Status: "failed"}, {ID: "live-b", Status: "passed"}},
			Evidence: []smokeEvidenceWire{{Kind: "run", Path: "runs/run-fail.json"}},
			Issues:  []SmokeIssue{{ID: "ISS-1", Status: "open", Path: "issues/ISS-1.md", TestID: "live-a", Severity: "high", Title: "boom", Summary: "observed failure", Theory: "why", Evidence: "ev", Action: "act"}},
		},
	}
	author := &smokeAuthorRuntime{}
	service = NewService(root).WithRuntime(author).WithProcessRunner(runner).WithSmokeSettings(DefaultSmokeSettings()).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "test/model"}, StageSmoke: {Model: "test/author"}})
	result, err := service.RunSmoke(context.Background(), "proj", "01", SmokeRequest{})
	if err != nil || result.Verdict != SmokeFailVerdict {
		t.Fatalf("baseline failing run: verdict=%s err=%v result=%+v", result.Verdict, err, err)
	}
	state, stateErr := LoadFlowState(root, sp)
	if stateErr != nil || state.Smoke == nil || state.Smoke.Verdict != SmokeFailVerdict || state.Smoke.LastComplete == nil {
		t.Fatalf("baseline state: %+v err=%v", state.Smoke, stateErr)
	}
	before, _ := os.ReadFile(filepath.Join(sp.Path, "smoke.md"))

	gauntletEvidenceFile(t, harness, "run-diag.json")
	runner.run = smokeRunResponse{SchemaVersion: 1, ProtocolVersion: "1.0", HarnessID: "fake", RunID: "run-diag", ScopeKind: "test", Scope: []string{"live-b"},
		Counts: SmokeCountsWire{Total: 1, Passed: 1}, DurationMs: 3,
