	diag, err := service.RunSmoke(context.Background(), "proj", "01", SmokeRequest{Test: "live-b"})
	if err != nil {
		t.Fatalf("diagnostic run failed: %v", err)
	}
	t.Logf("diag: status=%s verdict=%s diagnosticOnly=%t", diag.Status, diag.Verdict, diag.DiagnosticOnly)
	if !diag.DiagnosticOnly {
		t.Fatalf("expected diagnostic-only selection")
	}
	after, _ := os.ReadFile(filepath.Join(sp.Path, "smoke.md"))
	if string(after) != string(before) {
		t.Logf("artifact changed (unexpected for diagnostic run)")
	}
	state, stateErr = LoadFlowState(root, sp)
	if stateErr != nil {
		t.Fatal(stateErr)
	}
	t.Logf("after diagnostic rerun: state.verdict=%q state.runId=%q lastComplete.verdict=%q lastComplete.digest==state.digest=%t",
