	t.Logf("verification: assessment=%s smoke.fresh=%t smoke.verdict=%s next=%s", status.Assessment, status.Smoke.Fresh, status.Smoke.Verdict, status.NextAction)
	vr, _ := service.ValidateSmoke("proj", "01")
	t.Logf("validate findings=%d", len(vr.Findings))
	// Contract under test (TRD 18.9.2): a narrow passing rerun does not replace
